static std::random_device rd;
static std::mt19937 gen(rd());
std::normal_distribution<double> nd(0.0, 1.0);
assert(numberOfChecks % 2 == 1);
int insideCount = 0;
const double farDist = 1e9; // sufficiently large to be outside any mesh
for (int i = 0; i < numberOfChecks; ++i) {
    double dx, dy, dz;
    // generate a non‑zero random direction
    do {
        dx = nd(gen);
        dy = nd(gen);
        dz = nd(gen);
    } while (dx == 0.0 && dy == 0.0 && dz == 0.0);
    double len = std::sqrt(dx * dx + dy * dy + dz * dz);
    dx /= len; dy /= len; dz /= len;
    cg3::Point3d farPoint(p.x() + dx * farDist,
                          p.y() + dy * farDist,
                          p.z() + dz * farDist);
    int intersected = tree.numberIntersectedPrimitives(p, farPoint);
    if (intersected % 2 == 1)
        ++insideCount;
}
return (insideCount > numberOfChecks / 2);

